    fn get_gss_node(&self, nonterminal_id: NonterminalId, input_index: u32) -> Option<GssNodeId> {
        self.gss_nodes_index.get(
            &self.gss_nodes,
            GSSNodeKey {
                nonterminal_id,
                input_index,
            },
        )
    }
    fn add_gss_node(
        &mut self,
        nonterminal_id: NonterminalId,
        input_index: u32,
        gss_node_id: GssNodeId,
    ) {
        let key = GSSNodeKey {
            nonterminal_id,
            input_index,
        };
        self.gss_nodes_index
            .insert(&self.gss_nodes, key, gss_node_id);
    }
    fn new_gss_node(&mut self, nonterminal_id: NonterminalId, input_index: u32) -> GssNodeId {
        record!(self, GSSNodeCreated, nonterminal_id, input_index);
        self.gss_nodes
            .push(GSSNode::new(nonterminal_id, input_index))
    }
    fn start_gss_node_id(&self) -> Option<GssNodeId> {
        self.start_gss_node_id
    }
    fn set_start_gss_node_id(&mut self, id: GssNodeId) {
        self.start_gss_node_id = Some(id);
    }
    fn gss_node(&self, id: GssNodeId) -> &GSSNode<'arena> {
        &self.gss_nodes[id]
    }
    fn gss_node_mut(&mut self, id: GssNodeId) -> &mut GSSNode<'arena> {
        &mut self.gss_nodes[id]
    }
    fn sppf_node(&self, id: SPPFNodeId) -> &SPPFNode {
        &self.sppf_nodes[id]
    }
    fn sppf_node_mut(&mut self, id: SPPFNodeId) -> &mut SPPFNode {
        &mut self.sppf_nodes[id]
    }
    fn add_descriptor(&mut self, descriptor: Descriptor) {
        record!(
            self,
            DescriptorAdded,
            descriptor.input_index,
            descriptor.slot_id,
            descriptor.sppf_node_id,
            descriptor.gss_node_id
        );
        #[cfg(feature = "instrument")]
        self.increment_descriptor_count();
        self.descriptors.push(descriptor);
        #[cfg(feature = "instrument")]
        {
            if self.descriptors.len() > self.descriptors_peak {
                self.descriptors_peak = self.descriptors.len();
            }
        }
    }
    fn next_descriptor(&mut self) -> Option<Descriptor> {
        self.descriptors.pop()
    }
    fn clear_descriptors(&mut self) {
        self.descriptors.clear();
    }
    fn add_terminal_node(&mut self, terminal_node: TerminalNode) -> SPPFNodeId {
        record!(
            self,
            TerminalNodeCreated,
            terminal_node.terminal_id,
            terminal_node.span
        );
        let key = TerminalNodeKey {
            terminal_id: terminal_node.terminal_id,
            span: terminal_node.span,
        };
        let terminal_node_id = self.sppf_nodes.push(SPPFNode::Terminal(terminal_node));
        self.terminal_nodes_index
            .insert(&self.sppf_nodes, key, terminal_node_id);
        terminal_node_id
    }
    fn add_nonterminal_node(&mut self, nonterminal_node: NonterminalNode) -> SPPFNodeId {
        record!(
            self,
            NonterminalNodeCreated,
            nonterminal_node.nonterminal_id,
            nonterminal_node.span,
            nonterminal_node.child
        );
        self.sppf_nodes
            .push(SPPFNode::Nonterminal(nonterminal_node))
    }
    #[inline(never)]
    fn add_intermediate_node(
        &mut self,
        intermediate_node: IntermediateNode,
        add_to_index: bool,
    ) -> SPPFNodeId {
        record!(
            self,
            IntermediateNodeCreated,
            intermediate_node.slot_id,
            intermediate_node.span,
            intermediate_node.child.0,
            intermediate_node.child.1
        );
        let key = IntermediateNodeKey {
            slot_id: intermediate_node.slot_id,
            span: intermediate_node.span,
            env: intermediate_node.env,
        };
        let intermediate_node_id = self
            .sppf_nodes
            .push(SPPFNode::Intermediate(intermediate_node));
        if add_to_index {
            self.intermediate_nodes_index
                .insert(&self.sppf_nodes, key, intermediate_node_id);
        }
        intermediate_node_id
    }
    fn input(&self) -> &'i Input {
        self.scanner.input
    }
    fn count_sppf_nodes(&self) -> usize {
        self.sppf_nodes.len()
    }
    #[cfg(feature = "instrument")]
    fn increment_descriptor_count(&mut self) {
        self.descriptors_count += 1;
    }
    #[cfg(feature = "instrument")]
    fn count_descriptors(&self) -> usize {
        self.descriptors_count
    }
    #[cfg(feature = "instrument")]
    fn count_gss_nodes(&self) -> usize {
        self.gss_nodes.len()
    }
    #[cfg(feature = "instrument")]
    fn count_gss_edges(&self) -> usize {
        self.gss_nodes.values().map(|n| n.edges().len()).sum()
    }
    #[cfg(feature = "instrument")]
    fn count_nonterminal_nodes(&self) -> usize {
        self.sppf_nodes
            .values()
            .filter(|n| matches!(n, SPPFNode::Nonterminal(_)))
            .count()
    }
    #[cfg(feature = "instrument")]
    fn count_intermediate_nodes(&self) -> usize {
        self.sppf_nodes
            .values()
            .filter(|n| matches!(n, SPPFNode::Intermediate(_)))
            .count()
    }
    #[cfg(feature = "instrument")]
    fn count_terminal_nodes(&self) -> usize {
        self.sppf_nodes
            .values()
            .filter(|n| matches!(n, SPPFNode::Terminal(_)))
            .count()
    }
    #[cfg(feature = "instrument")]
    fn count_ambiguous_nodes(&self) -> usize {
        self.sppf_nodes
            .values()
            .filter(|n| match n {
                SPPFNode::Nonterminal(nn) => nn.ambiguous,
                SPPFNode::Intermediate(in_) => in_.ambiguous,
                SPPFNode::Terminal(_) => false,
            })
            .count()
    }
    #[inline]
    fn lookup_intermediate_node(
        &self,
        slot_id: SlotId,
        left_extent: u32,
        right_extent: u32,
        env: Option<EnvId>,
    ) -> Option<SPPFNodeId> {
        let span = Span::new(left_extent, right_extent);
        self.intermediate_nodes_index
            .get(&self.sppf_nodes, IntermediateNodeKey { slot_id, span, env })
    }
    fn lookup_terminal_node(
        &self,
        terminal_id: TerminalId,
        left_extent: u32,
        right_extent: u32,
    ) -> Option<SPPFNodeId> {
        let span = Span::new(left_extent, right_extent);
        self.terminal_nodes_index
            .get(&self.sppf_nodes, TerminalNodeKey { terminal_id, span })
    }
    fn gss_nodes<'p>(&'p self) -> impl Iterator<Item = (GssNodeId, &'p GSSNode<'arena>)>
    where
        'arena: 'p,
    {
        self.gss_nodes.iter()
    }
    #[inline]
    fn add_intermediate_node_child(
        &mut self,
        node: SPPFNodeId,
        child1: SPPFNodeId,
        child2: SPPFNodeId,
    ) {
        self.intermediate_nodes_children
            .push((node, (child1, child2)));
    }
    fn add_nonterminal_node_child(
        &mut self,
        node: SPPFNodeId,
        child: SPPFNodeId,
        return_slot: SlotId,
    ) {
        self.nonterminal_nodes_children
            .push((node, (child, return_slot)));
    }
    fn intermediate_nodes_children_map(
        &self,
    ) -> &FxHashMap<SPPFNodeId, Vec<(SPPFNodeId, SPPFNodeId)>> {
        self.intermediate_nodes_children_map.get_or_init(|| {
            let mut map: FxHashMap<SPPFNodeId, Vec<(SPPFNodeId, SPPFNodeId)>> =
                FxHashMap::default();
            for (k, v) in &self.intermediate_nodes_children {
                map.entry(*k).or_default().push(*v);
            }
            map
        })
    }
    fn nonterminal_nodes_children_map(&self) -> &FxHashMap<SPPFNodeId, Vec<(SPPFNodeId, SlotId)>> {
        self.nonterminal_nodes_children_map.get_or_init(|| {
            let mut map: FxHashMap<SPPFNodeId, Vec<(SPPFNodeId, SlotId)>> = FxHashMap::default();
            for (k, v) in &self.nonterminal_nodes_children {
                map.entry(*k).or_default().push(*v);
            }
            map
        })
    }
    #[cfg(feature = "debug-trace")]
    fn enable_trace(&mut self) {
        self.trace_events = Some(Vec::new());
    }
    #[cfg(feature = "debug-trace")]
    fn add_trace_event(&mut self, event: TraceEvent) {
        if let Some(trace_events) = &mut self.trace_events {
            trace_events.push(event);
        }
    }
    #[cfg(feature = "debug-trace")]
    fn trace_events(&self) -> &[TraceEvent] {
        self.trace_events.as_deref().unwrap_or(&[])
    }
    fn start_env(&mut self, start: NonterminalId) -> Option<EnvId> {
        match start {
            NonterminalId(419) => {
                let arena = self.vec_arena;
                let (env_id, env) = self.new_env();
                env.bind(BINDING_P, 0, arena);
                Some(env_id)
            }
            NonterminalId(420) => {
                let arena = self.vec_arena;
                let (env_id, env) = self.new_env();
                env.bind(BINDING_P, 0, arena);
                Some(env_id)
            }
            NonterminalId(421) => {
                let arena = self.vec_arena;
                let (env_id, env) = self.new_env();
                env.bind(BINDING_P, 0, arena);
                Some(env_id)
            }
            _ => None,
        }
    }
    // True if a local ambiguity node was added during parsing. This does not guarantee the
    // ambiguity is reachable from the root, so a tree walk is still needed to confirm it.
    fn ambiguity_node_added(&self) -> bool {
        !self.intermediate_nodes_children.is_empty() || !self.nonterminal_nodes_children.is_empty()
    }
    fn add_start_gss_node(
        &mut self,
        nonterminal_id: NonterminalId,
        input_index: u32,
        gss_node_id: GssNodeId,
    ) {
        match nonterminal_id {
            NonterminalId(419) => self.add_gss_node_expression(input_index, 0, gss_node_id),
            NonterminalId(420) => self.add_gss_node_lambda(input_index, 0, gss_node_id),
            NonterminalId(421) => self.add_gss_node_lambda_body(input_index, 0, gss_node_id),
            _ => self.add_gss_node(nonterminal_id, input_index, gss_node_id),
        }
    }
    fn new_env(&mut self) -> (EnvId, &mut Env<'arena>) {
        let id = self.envs.push(Env::default());
        (id, &mut self.envs[id])
    }
    fn lookup(&self, name: BindingId, env_id: EnvId) -> i32 {
        let env = &self.envs[env_id];
        env.get(name)
    }
    fn clone_env(&mut self, source: EnvId) -> (EnvId, &mut Env<'arena>) {
        let bindings = self.envs[source].bindings.clone();
        let (new_id, new_env) = self.new_env();
        new_env.bindings = bindings;
        (new_id, new_env)
    }
    fn bind_return_value(
        &mut self,
        return_slot: SlotId,
        env: Option<EnvId>,
        value: i32,
    ) -> Option<EnvId> {
        let bindings: &[(BindingId, i32)] = match return_slot {
            SlotId(2764) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2770) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2780) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2790) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2800) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2810) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2820) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2831) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2850) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2860) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2870) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2880) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2890) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2900) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2914) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2924) => &[(BINDING_R_PR, (value) >> 16)],
            SlotId(2927) => &[(BINDING_R_PR, value)],
            SlotId(2934) => &[(BINDING_R_PR, value)],
            SlotId(2937) => &[(BINDING_R_PR, (value) >> 16)],
            _ => return env,
        };
        let arena = self.vec_arena;
        let (id, target) = match env {
            Some(id) => self.clone_env(id),
            None => self.new_env(),
        };
        for &(name, value) in bindings {
            target.bind(name, value, arena);
        }
        Some(id)
    }
    fn envs<'p>(&'p self) -> impl Iterator<Item = &'p Env<'arena>>
    where
        'arena: 'p,
    {
        self.envs.values()
    }
    #[cfg(feature = "instrument")]
    fn record_stats(&self) -> iguana_runtime::instrument::Stats {
        let mut stats = iguana_runtime::instrument::Stats::new();
        stats.descriptors_count = self.count_descriptors();
        stats.descriptors_peak = self.descriptors_peak;
        stats.envs_count = self.envs.len();
        stats.gss_nodes_count = self.count_gss_nodes();
        stats.gss_edges_count = self.count_gss_edges();
        stats.nonterminal_nodes_count = self.count_nonterminal_nodes();
        stats.intermediate_nodes_count = self.count_intermediate_nodes();
        stats.terminal_nodes_count = self.count_terminal_nodes();
        stats.ambiguous_nodes_count = self.count_ambiguous_nodes();
        for (_, node) in self.gss_nodes() {
            stats.record("GssNode::edges: InlineVec", node.edges().len());
            stats.record(
                "GssNode::popped_elements: InlineMap",
                node.popped_elements().len(),
            );
        }
        for env in self.envs() {
            stats.record("Env::bindings: Bindings", env.bindings.len());
        }
        stats.record(
            "Parser::intermediate_nodes_index",
            self.intermediate_nodes_index.len(),
        );
        stats.record(
            "Parser::terminal_nodes_index",
            self.terminal_nodes_index.len(),
        );
        stats.record("Parser::gss_nodes_index", self.gss_nodes_index.len());
        stats.record(
            "Parser::gss_nodes_index_expression",
            self.gss_nodes_index_expression.len(),
        );
        stats.record(
            "Parser::gss_nodes_index_lambda",
            self.gss_nodes_index_lambda.len(),
        );
        stats.record(
            "Parser::gss_nodes_index_lambda_body",
            self.gss_nodes_index_lambda_body.len(),
        );
        for (nt_id, pos) in &self.ll1_call_log {
            let name = Self::Grammar::nonterminal_display_name(*nt_id);
            stats.record_ll1_call(name, *pos);
        }
        stats
    }
