    #[inline(always)]
    fn parse_plus_54_ll1_body(&mut self, i: u32) -> Option<(u32, SPPFNodeId)> {
        let left_extent = i;
        let (base_pos_0, base_node_0) = self.parse_alt_19_ll1(i, None)?;
        let mut current = base_node_0;
        let mut j = base_pos_0;
        current = self.add_nonterminal_node(NonterminalNode {
            nonterminal_id: NonterminalId(281),
            return_slot: SlotId(2095),
            span: Span {
                left_extent,
                right_extent: j,
            },
            child: current,
            ambiguous: false,
        });
        #[allow(clippy::while_let_loop)]
        loop {
            let Some((pos_0, node_0)) = self.parse_alt_19_ll1(j, None) else {
                break;
            };
            j = pos_0;
            current = self.create_intermediate_node_ll1(
                SlotId(2093),
                left_extent,
                pos_0,
                current,
                node_0,
            );
            current = self.add_nonterminal_node(NonterminalNode {
                nonterminal_id: NonterminalId(281),
                return_slot: SlotId(2093),
                span: Span {
                    left_extent,
                    right_extent: j,
                },
                child: current,
                ambiguous: false,
            });
        }
        Some((j, current))
    }
