    fn get_gss_node_expression(&self, input_index: u32, p: i32) -> Option<GssNodeId> {
        self.gss_nodes_index_expression
            .get(&(input_index, p))
            .copied()
    }
    fn get_gss_node_lambda(&self, input_index: u32, p: i32) -> Option<GssNodeId> {
        self.gss_nodes_index_lambda.get(&(input_index, p)).copied()
    }
    fn get_gss_node_lambda_body(&self, input_index: u32, p: i32) -> Option<GssNodeId> {
        self.gss_nodes_index_lambda_body
            .get(&(input_index, p))
            .copied()
    }
    fn add_gss_node_expression(&mut self, input_index: u32, p: i32, gss_node_id: GssNodeId) {
        self.gss_nodes_index_expression
            .insert((input_index, p), gss_node_id);
    }
    fn add_gss_node_lambda(&mut self, input_index: u32, p: i32, gss_node_id: GssNodeId) {
        self.gss_nodes_index_lambda
            .insert((input_index, p), gss_node_id);
    }
    fn add_gss_node_lambda_body(&mut self, input_index: u32, p: i32, gss_node_id: GssNodeId) {
        self.gss_nodes_index_lambda_body
            .insert((input_index, p), gss_node_id);
    }
    fn get_or_create_epsilon_node(&mut self, i: u32) -> SPPFNodeId {
        if let Some(existing) = self.epsilon_nodes[i as usize] {
            record!(self, TerminalNodeFound, existing);
            return existing;
        }
        let span = Span::new(i, i);
        let terminal_id = TerminalId(160);
        record!(self, TerminalNodeCreated, terminal_id, span);
        let node_id = self
            .sppf_nodes
            .push(SPPFNode::Terminal(TerminalNode { terminal_id, span }));
        self.epsilon_nodes[i as usize] = Some(node_id);
        node_id
    }
    #[inline(never)]
    fn add_failure_at_farthest_index(
        &mut self,
        input_index: u32,
        slot_id: SlotId,
        gss_node_id: Option<GssNodeId>,
        kind: GLLFailureKind,
    ) {
        if input_index > self.failures_index {
            self.failures.clear();
            self.failures_index = input_index;
        }
        self.failures.push(GLLFailure {
            input_index,
            slot_id,
            gss_node_id,
            kind,
        });
    }
